1	import { useState, useEffect, createContext, useContext } from "react";
2	import { supabase } from "@/integrations/supabase/client";
3	import type { User, Session } from "@supabase/supabase-js";
4	
5	interface AuthContextType {
6	  user: User | null;
7	  session: Session | null;
8	  loading: boolean;
9	  isAdmin: boolean;
10	  profile: { credits: number; subscription_credits: number; topup_credits: number; bonus_credits: number; inbox_email: string | null; plan: string; email_enabled: boolean; auto_rank_enabled: boolean; subscription_ends_at: string | null } | null;
11	  signOut: () => Promise<void>;
12	  refreshProfile: () => Promise<void>;
13	}
14	
15	const AuthContext = createContext<AuthContextType>({
16	  user: null,
17	  session: null,
18	  loading: true,
19	  isAdmin: false,
20	  profile: null,
21	  signOut: async () => {},
22	  refreshProfile: async () => {},
23	});
24	
25	export const useAuth = () => useContext(AuthContext);
26	
27	export const AuthProvider = ({ children }: { children: React.ReactNode }) => {
28	  const [user, setUser] = useState<User | null>(null);
29	  const [session, setSession] = useState<Session | null>(null);
30	  const [loading, setLoading] = useState(true);
31	  const [isAdmin, setIsAdmin] = useState(false);
32	  const [profile, setProfile] = useState<AuthContextType["profile"]>(null);
33	
34	  const fetchProfile = async (userId: string) => {
35	    try {
36	      const { data } = await supabase
37	        .from("profiles")
38	        .select("credits, subscription_credits, topup_credits, bonus_credits, inbox_email, plan, email_enabled, auto_rank_enabled, subscription_ends_at")
39	        .eq("user_id", userId)
40	        .single();
41	      if (data) setProfile(data);
42	    } catch (err) {
43	      console.error("Error fetching profile:", err);
44	    }
45	  };
46	
47	  const fetchRole = async (userId: string) => {
48	    try {
49	      const { data } = await supabase
50	        .from("user_roles")
51	        .select("role")
52	        .eq("user_id", userId);
53	      setIsAdmin(data?.some((r: any) => r.role === "admin") ?? false);
54	    } catch (err) {
55	      console.error("Error fetching role:", err);
56	    }
57	  };
58	
59	  const refreshProfile = async () => {
60	    if (user) await fetchProfile(user.id);
61	  };
62	
63	  useEffect(() => {
64	    const { data: { subscription } } = supabase.auth.onAuthStateChange(
65	      async (_event, session) => {
66	        setSession(session);
67	        setUser(session?.user ?? null);
68	        if (session?.user) {
69	          // Use setTimeout to avoid Supabase deadlock, but await results before setting loading=false
70	          setTimeout(async () => {
71	            await Promise.all([
72	              fetchProfile(session.user.id),
73	              fetchRole(session.user.id),
74	            ]);
75	          }, 0);
76	        } else {
77	          setProfile(null);
78	          setIsAdmin(false);
79	        }
80	        setLoading(false);
81	      }
82	    );
83	
84	    supabase.auth.getSession().then(async ({ data: { session } }) => {
85	      setSession(session);
86	      setUser(session?.user ?? null);
87	      if (session?.user) {
88	        await Promise.all([
89	          fetchProfile(session.user.id),
90	          fetchRole(session.user.id),
91	        ]);
92	      }
93	      setLoading(false);
94	    });
95	
96	    return () => subscription.unsubscribe();
97	  }, []);
98	
99	  // Refresh profile on window focus and periodically to keep credits current
100	  useEffect(() => {
101	    if (!user) return;
102	
103	    const handleFocus = () => fetchProfile(user.id);
104	    window.addEventListener("focus", handleFocus);
105	
106	    const interval = setInterval(() => fetchProfile(user.id), 120_000);
107	
108	    return () => {
109	      window.removeEventListener("focus", handleFocus);
110	      clearInterval(interval);
111	    };
112	  }, [user?.id]);
113	
114	  const signOut = async () => {
115	    await supabase.auth.signOut();
116	    setUser(null);
117	    setSession(null);
118	    setProfile(null);
119	    setIsAdmin(false);
120	  };
121	
122	  return (
123	    <AuthContext.Provider value={{ user, session, loading, isAdmin, profile, signOut, refreshProfile }}>
124	      {children}
125	    </AuthContext.Provider>
126	  );
127	};
